487	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
488	    @Override
489	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
490	        Owner owner = this.clinicService.findOwnerById(ownerId);
491	        if (owner == null) {
492	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
493	        }
494	        HttpHeaders headers = new HttpHeaders();
495	        Pet pet = petMapper.toPet(petFieldsDto);
496	        owner.setId(ownerId);
497	        pet.setOwner(owner);
498	        pet.getType().setName(null);
499	        this.clinicService.savePet(pet);
500	        PetDto petDto = petMapper.toPetDto(pet);
501	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
502	            .buildAndExpand(pet.getId()).toUri());
503	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
504	    }
