506	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
507	    @Override
508	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
509	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
510	        if (currentOwner != null) {
511	            Pet currentPet = this.clinicService.findPetById(petId);
512	            if (currentPet != null) {
513	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
514	                currentPet.setName(petFieldsDto.getName());
515	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
516	                this.clinicService.savePet(currentPet);
517	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
518	            }
519	        }
520	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
521	    }
