523	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
524	    @Override
525	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
526	        HttpHeaders headers = new HttpHeaders();
527	        Visit visit = visitMapper.toVisit(visitFieldsDto);
528	        Pet pet = new Pet();
529	        pet.setId(petId);
530	        visit.setPet(pet);
531	        this.clinicService.saveVisit(visit);
532	        VisitDto visitDto = visitMapper.toVisitDto(visit);
533	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
534	            .buildAndExpand(visit.getId()).toUri());
